-- calc_assertions_name
-- Field: Assertions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_assertions_name(p_assertion_id TEXT)
RETURNS TEXT AS $$
