-- calc_assessments_blocked_count
-- Field: Assessments.BlockedCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assessments_blocked_count(p_assessment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((calc_prerequisites_blocked(prerequisite_id))::numeric), 0) FROM prerequisites WHERE conclusion_key = (SELECT NULLIF(assertion, '') FROM assessments WHERE assessment_id = p_assessment_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assessments_proof_blocked_count
-- Field: Assessments.ProofBlockedCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assessments_proof_blocked_count(p_assessment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((calc_prerequisites_proof_blocked(prerequisite_id))::numeric), 0) FROM prerequisites WHERE conclusion_key = (SELECT NULLIF(assertion, '') FROM assessments WHERE assessment_id = p_assessment_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assessments_current_status
-- Field: Assessments.CurrentStatus
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_assessments_current_status(p_assessment_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((calc_assessments_blocked_count(p_assessment_id))::NUMERIC, 0) > 0 THEN ('BLOCKED')::text ELSE (calc_assessments_effective_status(p_assessment_id))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_assessments_proof_eligible
-- Field: Assessments.ProofEligible
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assessments_proof_eligible(p_assessment_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((calc_assessments_proof_blocked_count(p_assessment_id))::NUMERIC, 0) = 0 THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_assessments_support_count
-- Field: Assessments.SupportCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assessments_support_count(p_assessment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM evidence_links WHERE assertion = (SELECT NULLIF(assertion, '') FROM assessments WHERE assessment_id = p_assessment_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assessments_evidence_gap
-- Field: Assessments.EvidenceGap
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assessments_evidence_gap(p_assessment_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(COALESCE(calc_assessments_effective_status(p_assessment_id), '') = 'FINITE_VERIFIED', FALSE) AND COALESCE(COALESCE((calc_assessments_support_count(p_assessment_id))::NUMERIC, 0) = 0, FALSE) AND COALESCE(COALESCE((calc_assessments_is_model_decided(p_assessment_id))::NUMERIC, 0) = 0, FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_assessments_ancestor_blocked_count
-- Field: Assessments.AncestorBlockedCount
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assessments_ancestor_blocked_count(p_assessment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_assessments_blocked_count(p_assessment_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(1, 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_assessments_self_usable(p_assessment_id)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assessments_is_at_risk
-- Field: Assessments.IsAtRisk
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assessments_is_at_risk(p_assessment_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(COALESCE((calc_assessments_self_usable(p_assessment_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((calc_assessments_ancestor_blocked_count(p_assessment_id))::NUMERIC, 0) > 0, FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_assessments_ancestor_count
-- Field: Assessments.AncestorCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assessments_ancestor_count(p_assessment_id TEXT)
