-- calc_strategy_steps_goal_prerequisite_key
-- Field: StrategySteps.GoalPrerequisiteKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_strategy_steps_goal_prerequisite_key(p_strategy_step_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT(calc_strategy_steps_strategy_goal(p_strategy_step_id), '-', (SELECT NULLIF(assertion, '') FROM strategy_steps WHERE strategy_step_id = p_strategy_step_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_strategy_steps_is_open
-- Field: StrategySteps.IsOpen
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_strategy_steps_is_open(p_strategy_step_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(calc_strategy_steps_status_group(p_strategy_step_id), '') = 'Open' THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_strategy_steps_is_established
-- Field: StrategySteps.IsEstablished
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_strategy_steps_is_established(p_strategy_step_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_strategy_steps_status_group(p_strategy_step_id) AS val) SELECT (CASE WHEN (COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Proved', FALSE) OR COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Checked', FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_strategy_steps_blocks_goal
-- Field: StrategySteps.BlocksGoal
-- Type: calculated | DataType: integer | Returns: INTEGER


