  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rule_table_entries_output_value(p_rule_table_entry_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, (calc_rule_table_entries_mirror_index(p_rule_table_entry_id))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_rule_table_entries_complement_weight
