-- calc_time_steps_cumulative_cell_updates
-- Field: TimeSteps.CumulativeCellUpdates
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_time_steps_cumulative_cell_updates__compute(p_time_step_id TEXT)
