-- calc_cells_column_density
-- Field: Cells.ColumnDensity
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_cells_column_density(p_cell_id TEXT)
RETURNS NUMERIC AS $$
