$$ LANGUAGE sql STABLE;

-- calc_cells_run_start
-- Field: Cells.RunStart
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_run_start__compute(p_cell_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_cells_value(p_cell_id) AS val) SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM cells WHERE cell_id = p_cell_id))::NUMERIC, 0) = 1 THEN ((SELECT run_start_cache FROM cells WHERE cell_id = p_cell_id))::text ELSE (CASE WHEN COALESCE((calc_cells_is_column_start(p_cell_id))::NUMERIC, 0) = 1 THEN (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_cells_background_value(p_cell_id)) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((SELECT time FROM cells WHERE cell_id = p_cell_id))::text END)::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_cells_center_value(p_cell_id)) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN (calc_cells_prior_run_start(p_cell_id))::text ELSE ((SELECT time FROM cells WHERE cell_id = p_cell_id))::text END)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_run_length
-- Field: Cells.RunLength
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_run_length(p_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM cells WHERE cell_id = p_cell_id))::NUMERIC, 0) = 1 THEN ((SELECT run_length_cache FROM cells WHERE cell_id = p_cell_id))::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT time FROM cells WHERE cell_id = p_cell_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_cells_run_start(p_cell_id)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text END)::integer;
