-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_periodicity_candidates_is_refuted(p_periodicity_candidate_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(calc_periodicity_candidates_first_mismatch_from(p_periodicity_candidate_id), 0) <= COALESCE(calc_periodicity_candidates_last_onset(p_periodicity_candidate_id), 0) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_periodicity_candidates_agreement_run_from
-- Field: PeriodicityCandidates.AgreementRunFrom
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_periodicity_candidates_agreement_run_from__compute(p_periodicity_candidate_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((calc_periodicity_candidates_is_mismatch(p_periodicity_candidate_id))::NUMERIC, 0) = 1 THEN (0)::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT onset FROM periodicity_candidates WHERE periodicity_candidate_id = p_periodicity_candidate_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_periodicity_candidates_last_onset(p_periodicity_candidate_id)) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN (1)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_periodicity_candidates_next_agreement_run(p_periodicity_candidate_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_periodicity_candidates_in_bounded_domain
-- Field: PeriodicityCandidates.InBoundedDomain
