-- calc_left_consistency_checks_forced_next
-- Field: LeftConsistencyChecks.ForcedNext
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_left_consistency_checks_forced_next(p_left_consistency_check_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE(1, 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_left_consistency_checks_left_bit(p_left_consistency_check_id)) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_left_consistency_checks_is_consistent
-- Field: LeftConsistencyChecks.IsConsistent
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_left_consistency_checks_is_consistent(p_left_consistency_check_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM left_consistency_checks WHERE left_consistency_check_id = p_left_consistency_check_id))::NUMERIC, 0) = 1 THEN ((SELECT is_consistent_cache FROM left_consistency_checks WHERE left_consistency_check_id = p_left_consistency_check_id))::text ELSE (CASE WHEN COALESCE((calc_left_consistency_checks_is_one_time(p_left_consistency_check_id))::NUMERIC, 0) = 0 THEN (1)::text ELSE (CASE WHEN COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_left_consistency_checks_next_value(p_left_consistency_check_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_left_consistency_checks_forced_next(p_left_consistency_check_id)) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 0 THEN (1)::text ELSE (0)::text END)::text END)::text END)::integer;
