-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_periodic_words_least_period(p_periodic_word_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(MIN((shift)::numeric), 0) FROM word_shifts WHERE periodic_word = p_periodic_word_id AND calc_word_shifts_is_symmetry(word_shift_id) = 1))::integer;
$$ LANGUAGE sql STABLE;

-- calc_periodic_words_is_primitive
-- Field: PeriodicWords.IsPrimitive
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_periodic_words_is_primitive(p_periodic_word_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_periodic_words_least_period(p_periodic_word_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT length FROM periodic_words WHERE periodic_word_id = p_periodic_word_id)) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_periodic_words_is_in_b9_domain
-- Field: PeriodicWords.IsInB9Domain
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_periodic_words_is_in_b9_domain(p_periodic_word_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(COALESCE((calc_periodic_words_is_nonconstant(p_periodic_word_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((calc_periodic_words_is_primitive(p_periodic_word_id))::NUMERIC, 0) = 1, FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

