-- calc_tail_cells_value
-- Field: TailCells.Value
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_tail_cells_value__compute(p_tail_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT time FROM tail_cells WHERE tail_cell_id = p_tail_cell_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tail_cells_onset(p_tail_cell_id)) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN (calc_tail_cells_real_value(p_tail_cell_id))::text ELSE (MOD((FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tail_cells_rule_number(p_tail_cell_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, (calc_tail_cells_neighborhood(p_tail_cell_id))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC))::text END)::integer;
$$ LANGUAGE sql STABLE;

