-- calc_tolerance_checks_is_excursion
-- Field: ToleranceChecks.IsExcursion
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_tolerance_checks_is_excursion(p_tolerance_check_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tolerance_checks_abs_discrepancy(p_tolerance_check_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tolerance_checks_epsilon_denominator(p_tolerance_check_id)) AS v OFFSET 0) __safe_numeric), 0)), 0) > COALESCE((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tolerance_checks_epsilon_numerator(p_tolerance_check_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tolerance_checks_prefix_length(p_tolerance_check_id)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)), 0) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

