-- calc_color_counts_cone_count
-- Field: ColorCounts.ConeCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_color_counts_cone_count(p_color_count_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM cells WHERE "column" = (SELECT NULLIF("column", '') FROM color_counts WHERE color_count_id = p_color_count_id) AND calc_cells_state_key(cell_id) = (SELECT NULLIF(cell_state, '') FROM color_counts WHERE color_count_id = p_color_count_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_color_counts_occurrence_count
-- Field: ColorCounts.OccurrenceCount
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_color_counts_occurrence_count(p_color_count_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_color_counts_cone_count(p_color_count_id) AS val) SELECT (CASE WHEN COALESCE((SELECT NULLIF(cell_state, '') FROM color_counts WHERE color_count_id = p_color_count_id), '') = 'white' THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_color_counts_column_first_time(p_color_count_id)) AS v OFFSET 0) __safe_numeric), 0)))::text ELSE ((SELECT val FROM __erb_dedup_v1))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_color_counts_share
-- Field: ColorCounts.Share
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_color_counts_share(p_color_count_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_color_counts_occurrence_count(p_color_count_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_color_counts_depth(p_color_count_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0))) AS v OFFSET 0) __safe_numeric), 0), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_color_counts_share_deviation
-- Field: ColorCounts.ShareDeviation
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_color_counts_share_deviation(p_color_count_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_color_counts_share(p_color_count_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE(0.5, 0))))::numeric;
$$ LANGUAGE sql STABLE;

