-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_algorithms_is_admissible(p_algorithm_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE(1, 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT stores_answer FROM algorithms WHERE algorithm_id = p_algorithm_id)) AS v OFFSET 0) __safe_numeric), 0)))::integer;
