-- calc_algorithms_ratio_at_horizon
-- Field: Algorithms.RatioAtHorizon
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_algorithms_ratio_at_horizon(p_algorithm_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(MAX((calc_computations_effort_ratio(computation_id))::numeric), 0) FROM computations WHERE algorithm = p_algorithm_id AND calc_computations_is_horizon(computation_id) = 1))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_algorithms_ratio_at_half_horizon
-- Field: Algorithms.RatioAtHalfHorizon
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_algorithms_ratio_at_half_horizon(p_algorithm_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(MAX((calc_computations_effort_ratio(computation_id))::numeric), 0) FROM computations WHERE algorithm = p_algorithm_id AND calc_computations_is_half_horizon(computation_id) = 1))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_algorithms_is_ratio_growing
-- Field: Algorithms.IsRatioGrowing
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_algorithms_is_ratio_growing(p_algorithm_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(calc_algorithms_ratio_at_horizon(p_algorithm_id), 0) > COALESCE(calc_algorithms_ratio_at_half_horizon(p_algorithm_id), 0) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_algorithms_effort_holds
-- Field: Algorithms.EffortHolds
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_algorithms_effort_holds(p_algorithm_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM algorithms WHERE algorithm_id = p_algorithm_id))::NUMERIC, 0) = 1 THEN ((SELECT effort_holds_cache FROM algorithms WHERE algorithm_id = p_algorithm_id))::text ELSE (CASE WHEN COALESCE((calc_algorithms_is_admissible(p_algorithm_id))::NUMERIC, 0) = 1 THEN (calc_algorithms_is_ratio_growing(p_algorithm_id))::text ELSE (1)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

