$$ LANGUAGE sql STABLE;

-- calc_predicates_failing_count
-- Field: Predicates.FailingCount
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_predicates_failing_count(p_predicate_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM predicates WHERE predicate_id = p_predicate_id))::NUMERIC, 0) = 1 THEN ((SELECT failing_count_cache FROM predicates WHERE predicate_id = p_predicate_id))::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_predicates_instance_count(p_predicate_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_predicates_holding_count(p_predicate_id)) AS v OFFSET 0) __safe_numeric), 0)))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_predicates_is_refuted
