$$ LANGUAGE sql STABLE;

-- calc_predicates_is_verified
-- Field: Predicates.IsVerified
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_predicates_is_verified(p_predicate_id TEXT)
