$$ LANGUAGE sql STABLE;

-- calc_predicates_finite_verdict
-- Field: Predicates.FiniteVerdict
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_predicates_finite_verdict(p_predicate_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_predicates_instance_count(p_predicate_id) AS val), __erb_dedup_v2 AS (SELECT calc_predicates_failing_count(p_predicate_id) AS val) SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM predicates WHERE predicate_id = p_predicate_id))::NUMERIC, 0) = 1 THEN ((SELECT NULLIF(finite_verdict_cache, '') FROM predicates WHERE predicate_id = p_predicate_id))::text ELSE (CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) = 0 THEN ('NO INSTANCES')::text ELSE (CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v2))::NUMERIC, 0) = 0 THEN ('HOLDS ON EVERY INSTANCE')::text ELSE (CASE WHEN COALESCE(((SELECT failure_refutes FROM predicates WHERE predicate_id = p_predicate_id))::NUMERIC, 0) = 1 THEN (CONCAT('REFUTED BY ', (SELECT val FROM __erb_dedup_v2), ' OF ', (SELECT val FROM __erb_dedup_v1), ' INSTANCES'))::text ELSE (CONCAT((SELECT val FROM __erb_dedup_v2), ' OF ', (SELECT val FROM __erb_dedup_v1), ' UNDECIDED AT THE HORIZON'))::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

