-- calc_predicate_instances_witness
-- Field: PredicateInstances.Witness
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_predicate_instances_witness(p_predicate_instance_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_predicate_instances_instance_kind(p_predicate_instance_id) AS val) SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM predicate_instances WHERE predicate_instance_id = p_predicate_instance_id))::NUMERIC, 0) = 1 THEN ((SELECT witness_cache FROM predicate_instances WHERE predicate_instance_id = p_predicate_instance_id))::text ELSE (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'PeriodicityCandidate' THEN (calc_predicate_instances_candidate_witness(p_predicate_instance_id))::text ELSE (CASE WHEN (COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'TailCandidate', FALSE) OR COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'TailCandidateExcessBound', FALSE)) THEN (calc_predicate_instances_tail_kill_time(p_predicate_instance_id))::text ELSE (0)::text END)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_accelerator_claims_model_value
