-- Type: lookup | DataType: integer | Returns: INTEGER
-- Lookup: Value from related Cells


CREATE OR REPLACE FUNCTION calc_accelerator_claims_model_value(p_accelerator_claim_id TEXT)
RETURNS INTEGER AS $$
  SELECT calc_cells_value((SELECT cell FROM accelerator_claims WHERE accelerator_claim_id = p_accelerator_claim_id));
$$ LANGUAGE sql STABLE;

-- calc_accelerator_claims_name
