-- ============================================================================
-- SELF-REFERENCING LOOKUPS — memoised evaluation (see 06-refresh-memos.sql)
-- A table whose lookup reads its own rows recomputes every ancestor row on each
-- call. The original function is kept as <name>__compute; <name> now returns the
-- memoised value when present and otherwise falls back to __compute. Any write
-- to any table empties the memo (never stale); 06-refresh-memos.sql refills it.
-- ============================================================================

CREATE UNLOGGED TABLE IF NOT EXISTS erb_memo_rule_table_entries_output_value (id TEXT PRIMARY KEY, val INTEGER);
CREATE OR REPLACE FUNCTION calc_rule_table_entries_output_value(p_rule_table_entry_id TEXT)
RETURNS INTEGER AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM erb_memo_rule_table_entries_output_value WHERE id = p_rule_table_entry_id::text)
              THEN (SELECT val FROM erb_memo_rule_table_entries_output_value WHERE id = p_rule_table_entry_id::text)
              ELSE calc_rule_table_entries_output_value__compute(p_rule_table_entry_id) END;
$$ LANGUAGE sql STABLE;

