CREATE OR REPLACE FUNCTION erb_memo_invalidate() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM erb_memo_rule_table_entries_output_value) THEN DELETE FROM erb_memo_rule_table_entries_output_value; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_time_steps_cumulative_cell_updates) THEN DELETE FROM erb_memo_time_steps_cumulative_cell_updates; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_cells_value) THEN DELETE FROM erb_memo_cells_value; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_cells_column_ones) THEN DELETE FROM erb_memo_cells_column_ones; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_cells_run_start) THEN DELETE FROM erb_memo_cells_run_start; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_periodicity_candidates_first_mismatch_from) THEN DELETE FROM erb_memo_periodicity_candidates_first_mismatch_from; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_periodicity_candidates_agreement_run_from) THEN DELETE FROM erb_memo_periodicity_candidates_agreement_run_from; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_tail_cells_value) THEN DELETE FROM erb_memo_tail_cells_value; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_tail_checks_first_violation_from) THEN DELETE FROM erb_memo_tail_checks_first_violation_from; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_diagonals_least_period) THEN DELETE FROM erb_memo_diagonals_least_period; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_diagonals_doubles) THEN DELETE FROM erb_memo_diagonals_doubles; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_diagonals_previous_doubles) THEN DELETE FROM erb_memo_diagonals_previous_doubles; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_diagonals_ones_per_period) THEN DELETE FROM erb_memo_diagonals_ones_per_period; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_diagonals_previous_ones_per_period) THEN DELETE FROM erb_memo_diagonals_previous_ones_per_period; END IF;
  IF EXISTS (SELECT 1 FROM erb_memo_terms_rendered) THEN DELETE FROM erb_memo_terms_rendered; END IF;
  RETURN NULL;
END $$;
